/// <reference types="vite/client" />
import { onMounted, type Ref } from 'vue';

/**
 * [DEV ONLY] Diagnostic tool to detect hydration mismatches.
 * Checks if the rendered DOM element matches expected critical attributes.
 * 
 * @param elementRef The template ref of the root element
 * @param expectedId The ID generated by useStructureId
 * @param componentName Name of the component for logging
 */
export function useHydrationCheck(
  elementRef: Ref<HTMLElement | null>,
  expectedId: string,
  componentName: string
) {
  // Only run in development mode
  if (import.meta.env.PROD) return;

  onMounted(() => {
    const el = elementRef.value;
    if (!el) return;

    const renderedId = el.getAttribute('id');

    if (renderedId !== expectedId) {
      console.warn(
        `[StructureUI] 💧 Hydration Mismatch detected in <${componentName}>!\n` +
        `Expected ID (Server/Logic): "${expectedId}"\n` +
        `Rendered ID (Client DOM): "${renderedId}"\n` +
        `This may cause layout shifts or event listener issues.`
      );
    }
  });
}
